mapper.insert:
INSERT INTO sys_feedback (
    user_id, feedback_type, title, content, images, contact, status
) VALUES (
    #{userId}, #{feedbackType}, #{title}, #{content}, #{images}, #{contact}, #{status}
)

mapper.select:
SELECT f.id, f.user_id, u.nickname AS user_nickname, f.feedback_type, f.title, f.content, f.images, f.contact, f.status, f.reply_content, f.reply_time, f.handler_id, h.nickname AS handler_nickname, f.create_time FROM sys_feedback f LEFT JOIN sys_user u ON f.user_id = u.id LEFT JOIN sys_user h ON f.handler_id = h.id
f.status = #{status} AND f.feedback_type = #{feedbackType}
ORDER BY COALESCE(f.reply_time, f.create_time) DESC, f.create_time DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM sys_feedback

    status = #{status}
    AND feedback_type = #{feedbackType}

mapper.update:
UPDATE sys_feedback
SET title   = #{title},
    content = #{content},
    images  = #{images},
    contact = #{contact}
WHERE id = #{id}

UPDATE sys_feedback
SET reply_content = #{replyContent},
    status        = #{status}
WHERE id = #{id}

UPDATE sys_feedback
SET reply_content = #{replyContent},
    status        = #{status},
    handler_id    = #{handlerId},
    reply_time    = #{replyTime}
WHERE id = #{id}
